def semver_sort(versions):
    def parse_version(v):
        # Split build metadata first
        if '+' in v:
            version_part, build = v.split('+', 1)
        else:
            version_part = v
            build = ''

        # Split pre-release
        if '-' in version_part:
            base, prerelease = version_part.split('-', 1)
        else:
            base = version_part
            prerelease = ''

        # Parse base version
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
            prerelease_tuple = tuple(parse_prerelease_id(id) for id in prerelease_ids)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def parse_prerelease_id(id):
        if id.isdigit():
            return (0, int(id))  # numeric sorts first
        else:
            return (1, id)  # non-numeric sorts second

    def sort_key(item):
        v, original_index = item
        major, minor, patch, prerelease = parse_version(v)

        # For sorting: version without pre-release sorts after version with pre-release
        # So we need to handle this in the tuple
        if prerelease is None:
            # No pre-release: sorts after any pre-release of same base version
            prerelease_key = (1,)  # Higher value sorts later
        else:
            # Has pre-release: sorts before version without pre-release
            prerelease_key = (0, prerelease)

        return (major, minor, patch, prerelease_key, original_index)

    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for v, _ in sorted_versions]

